/* Quote approval -> verified deposit -> confirmed repair booking. */
function approvedQuoteTotal(j){return fromCash(j.quotes.filter(q=>q.status==='Approved').reduce((n,q)=>n+cash(q.amount),0))}
function depositSummary(j){const total=approvedQuoteTotal(j),required=fromCash(Math.round(cash(total)/2)),received=fromCash(j.invoices.reduce((n,i)=>n+cash(invoicePaid(i)),0));return {total,required,received,outstanding:fromCash(Math.max(0,cash(required)-cash(received)))}}
function needsDeposit(j){return !!j&&!j.callout&&!isAssessmentVisit(j)&&approvedQuoteTotal(j)>0&&!['Completed','In progress','Scheduled'].includes(j.status)&&depositSummary(j).outstanding>0}
const stageBeforeDeposit=jobStage;jobStage=function(j){const stage=stageBeforeDeposit(j);if(j.status==='Completed'&&!j.callout&&approvedQuoteTotal(j)>0&&j.invoices.reduce((n,i)=>n+cash(i.amount),0)<cash(approvedQuoteTotal(j)))return 'invoicing';return ['scheduling','new','assessment','quoting'].includes(stage)&&needsDeposit(j)?'deposit':stage};
stages.splice(stages.findIndex(s=>s[0]==='scheduling'),0,['deposit','Awaiting 50% deposit','Upload deposit invoice and verify payment']);
const actionBeforeDeposit=nextAction;nextAction=function(j){if(jobStage(j)==='deposit')return '50% deposit required: '+money(depositSummary(j).outstanding)+' still to receive. Upload invoice, then verify payment.';return actionBeforeDeposit(j)};
function depositPanel(j){if(j.callout||approvedQuoteTotal(j)<=0||role==='tenant')return '';const d=depositSummary(j);return `<div class="notice" style="margin:18px 0"><b>Quoted work · 50% deposit</b><p>Approved quote total: ${money(d.total)}<br>Deposit required: ${money(d.required)}<br>Verified payments received: ${money(d.received)}<br><b>${d.outstanding>0?'Deposit still required: '+money(d.outstanding):'Deposit received · ready to schedule'}</b></p>${role==='sevlink'&&d.outstanding>0?`<button class="secondary" onclick="jobDetail('${j.id}','invoices')">Invoices / record deposit payment</button>`:''}<p>Only bank-verified payments count toward the deposit. POP uploads remain pending until Sevlink verifies them.</p></div>`}
const detailBeforeDeposit=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeDeposit(jid,section);const j=getJob(jid);if(j&&role!=='tenant')$('#jobcontent').insertAdjacentHTML('afterbegin',depositPanel(j))};
const scheduleBeforeDeposit=renderSchedule;renderSchedule=function(j){if(needsDeposit(j)&&role!=='tenant'){$('#jobcontent').innerHTML='<h2>Awaiting 50% deposit</h2><p>Record the deposit invoice and verify payment before confirming the repair appointment. You can discuss a provisional date with the tenant.</p>'+depositPanel(j);return}scheduleBeforeDeposit(j)};
const saveScheduleBeforeDeposit=saveSchedule;saveSchedule=async function(jid,...args){if(needsDeposit(getJob(jid))){paymentSaveError('Verify the 50% deposit before confirming the repair booking. Open Invoices to record or verify payment.');return false}return saveScheduleBeforeDeposit(jid,...args)};
const privateSaveBeforeDeposit=savePrivateBooking;savePrivateBooking=async function(bid,record){if(record.confirmBooking&&needsDeposit(getJob(record.job))){paymentSaveError('Verify the 50% deposit before confirming the repair booking.');return false}return privateSaveBeforeDeposit(bid,record)};
const invoiceBeforeDeposit=invoiceForm;invoiceForm=function(jid){const j=getJob(jid);if(!j||role!=='sevlink')return;if(j.callout||approvedQuoteTotal(j)<=0)return invoiceBeforeDeposit(jid);const a=state.agencies.find(a=>a.id===j.agency),d=depositSummary(j),billed=fromCash(j.invoices.reduce((n,i)=>n+cash(i.amount),0)),remaining=fromCash(Math.max(0,cash(d.total)-cash(billed))),purpose=j.status==='Completed'?'Balance':billed<d.required?'Deposit':'Full';if(remaining<=0){jobDetail(jid,'invoices');paymentSaveError('The approved quote is already fully invoiced. Record payments on the existing invoice instead.');return}openForm('Upload '+(purpose==='Deposit'?'50% deposit':'balance')+' invoice.',`<div id="paymentSaveError" class="notice" role="alert" hidden></div><div class="notice">Approved quote: ${money(d.total)} · 50% deposit: ${money(d.required)}<br>Already invoiced: ${money(billed)} · Remaining to invoice: ${money(remaining)}<br>Use a new invoice number from your company system for each separate deposit or balance invoice.</div><label>Invoice type</label><select name="purpose"><option value="Deposit" ${purpose==='Deposit'?'selected':''}>50% deposit invoice</option><option value="Balance" ${purpose==='Balance'?'selected':''}>Remaining balance invoice</option><option value="Full" ${purpose==='Full'?'selected':''}>Full job invoice (deposit recorded as a payment)</option></select>${field('Company invoice number','number')}<div class="row"><div>${field('Invoice date','issueDate',todayKey(),'date')}</div><div>${field('Due date','dueDate',todayKey(),'date')}</div></div>${field('Bill to','billTo',a.name)}${field('Recipient email','email',a.email,'email')}<label>Invoice amount (ZAR)</label><input name="amount" type="number" min="0.01" max="${remaining}" step="0.01" required value="${purpose==='Deposit'?Math.min(Math.max(0,d.required-billed),remaining):remaining}"><label>Original company invoice (PDF / image, up to 5 MB)</label><input name="file" type="file" required accept="application/pdf,image/jpeg,image/png,image/webp">`,'Save invoice',async data=>{let file;try{file=await fileData(data.get('file'),quoteTypes)}catch(e){paymentSaveError(e.message);return}const result=await addCompanyInvoice(jid,{purpose:data.get('purpose'),quoteIds:j.quotes.filter(q=>q.status==='Approved').map(q=>q.id),number:data.get('number'),issueDate:data.get('issueDate'),dueDate:data.get('dueDate'),billTo:data.get('billTo'),email:data.get('email'),amount:Number(data.get('amount')),file});if(result){render();jobDetail(jid,'invoices');toast('Invoice saved. Email delivery remains a demo preview.')}else if(!$('#paymentSaveError')?.textContent)paymentSaveError('Invoice not saved. Review the fields and try again.')});const selector=modal.querySelector('select[name="purpose"]'),amount=modal.querySelector('input[name="amount"]');if(selector&&amount)selector.onchange=()=>amount.value=selector.value==='Deposit'?Math.min(Math.max(0,d.required-billed),remaining):remaining};
const addInvoiceBeforeDeposit=addCompanyInvoice;addCompanyInvoice=async function(jid,data){const j=getJob(jid);if(j&&!j.callout&&data.purpose&&approvedQuoteTotal(j)>0){const total=approvedQuoteTotal(j),existing=j.invoices.reduce((n,i)=>n+cash(i.amount),0);if(existing+cash(data.amount)>cash(total)){paymentSaveError('The combined invoices cannot exceed the approved quote total.');return false}if(data.purpose==='Balance'&&j.status!=='Completed'){paymentSaveError('Upload the remaining balance invoice after the repair is completed.');return false}}return addInvoiceBeforeDeposit(jid,data)};
const opsBeforeDeposit=renderOperations;renderOperations=function(){opsBeforeDeposit();if(selectedPod==='deposit'){document.querySelectorAll('.job-card .primary').forEach(button=>{button.textContent='Open deposit / invoices →';const source=button.getAttribute('onclick');if(source)button.setAttribute('onclick',source.replace(/,'comments'\)/,",'invoices')"))})}};

